func composeDirection(medium, mood, palette string) string {
	parts := make([]string, 0, 3)
	// Palette FIRST (2026-07-20, bugs_open/027 4b): the composed direction is
	// truncated at maxImageryDirectionInPrompt and the palette is both the
	// shortest field and the one carrying brand identity, so it must not be
	// the tail. A verbose medium+mood previously evicted the colours entirely
	// and the model invented an accent -- silently, and the image looked
	// deliberate. medium/mood are prose and degrade gracefully when clipped.
	if palette != "" {
		parts = append(parts, "colour palette: "+palette)
	}
	if medium != "" {
		parts = append(parts, medium)
	}
	if mood != "" {
		parts = append(parts, mood)
	}
	return strings.Join(parts, ". ")
}

func TestComposeDirectionKeepsPaletteUnderTruncation(t *testing.T) {
	// Real shape of the defect: gamesdesign.co.uk, 2026-07-19. The composed
	// direction exceeded 200 chars and the palette was the tail, so the
	// generated images came back in an invented accent colour.
	g := &imageryStyleGuide{Kinds: map[string]imageryStyleGuideKindOverride{
		"content_hero": {
			Medium:  "flat duotone editorial illustration",
			Mood:    "bold simple silhouette of the subject, minimal detail, legible at small size, precise, technical",
			Palette: "cyan #00bcd4 on near-black #121212, light grey accents",
		},
	}}
	direction := g.directionForKind("content_hero")
	if len(direction) <= maxImageryDirectionInPrompt {
		t.Fatalf("fixture must exceed the cap to exercise truncation; got %d", len(direction))
	}
	sent := direction
	if len(sent) > maxImageryDirectionInPrompt {
		sent = sent[:maxImageryDirectionInPrompt]
	}
	if !strings.Contains(sent, "#00bcd4") {
		t.Errorf("palette lost to truncation; the model would invent an accent.\nsent: %q", sent)
	}
}
